const api=(path,method='GET',body)=>window.SaleMaxWorkspace.request('email',path,{method,body});
const tabs=[['campaigns','Campaigns','الحملات'],['analytics','Analytics','التحليلات'],['templates','Templates','القوالب'],['inbox','Email Inbox','صندوق البريد'],['setup','Setup','الإعدادات']];
