const state={access:null,setup:null,analytics:null,templates:[],campaigns:[],threads:[],receivingReady:false,selectedThread:null,messages:[],tab:'campaigns',report:null,reportId:null,reportReturnTab:null,reportPage:1,reportSearch:'',reportStatus:'all',reportLoading:false,reportError:'',reportSerial:0,root:null,main:null,loading:false,error:'',toast:'',serial:0};
